package org.apache.commons.io.input;

import org.junit.Test;
import static org.junit.Assert.*;
import java.io.PipedReader;
import java.io.StringReader;
import org.apache.commons.io.input.BoundedReader;
import org.evosuite.runtime.EvoRunner;
import org.evosuite.runtime.EvoRunnerParameters;
import org.junit.runner.RunWith;

@RunWith(EvoRunner.class) @EvoRunnerParameters(mockJVMNonDeterminism = true, useVFS = true, useVNET = true, resetStaticState = true, separateClassLoader = false)
public class BoundedReader_ESTest extends BoundedReader_ESTest_scaffolding {

  /**
   * Reading into an array honors the character bound: with a limit of 1, asking
   * for 1 character into the buffer returns 1.
   */
  @Test(timeout = 4000)
  public void readIntoArrayReturnsRequestedCountWithinLimit() throws Throwable {
      StringReader underlying = new StringReader("KnLjCdWGnB@(}p3qC");
      BoundedReader boundedReader = new BoundedReader(underlying, 1);

      char[] buffer = new char[14];
      int charsRead = boundedReader.read(buffer, 1, 1);

      assertEquals(1, charsRead);
  }

  /**
   * After resetting, skipping past the (empty) content and then re-marking, a
   * single-character read reports EOF because there is nothing left to read.
   */
  @Test(timeout = 4000)
  public void readReturnsEofOnEmptySourceAfterResetSkipAndMark() throws Throwable {
      StringReader emptyUnderlying = new StringReader("");
      BoundedReader boundedReader = new BoundedReader(emptyUnderlying, 511);

      boundedReader.reset();
      boundedReader.skip(511);
      boundedReader.mark(511);

      int result = boundedReader.read();

      assertEquals(-1, result);
  }

  /**
   * A negative character limit means no characters may be read, so reading into
   * an array immediately reports EOF.
   */
  @Test(timeout = 4000)
  public void readIntoArrayReturnsEofWhenLimitIsNegative() throws Throwable {
      PipedReader underlying = new PipedReader();
      BoundedReader boundedReader = new BoundedReader(underlying, -1);

      char[] buffer = new char[14];
      int charsRead = boundedReader.read(buffer, 1, 1);

      assertEquals(-1, charsRead);
  }

  /**
   * Skipping returns the number of characters actually skipped from the source
   * ("@</'" has 4 characters), and a subsequent read after the source is
   * exhausted reports EOF.
   */
  @Test(timeout = 4000)
  public void skipReturnsSkippedCountThenReadReturnsEof() throws Throwable {
      StringReader underlying = new StringReader("@</'");
      BoundedReader boundedReader = new BoundedReader(underlying, 481);

      boundedReader.reset();
      long skipped = boundedReader.skip(481);
      assertEquals(4L, skipped);

      boundedReader.mark(1);
      int result = boundedReader.read();
      assertEquals(-1, result);
  }
}
